create table if not exists public.contact_messages(id uuid primary key default gen_random_uuid(),name text not null,email text not null,message text not null,created_at timestamptz not null default now()); alter table public.contact_messages enable row level security; drop policy if exists "Public can submit contact messages" on public.contact_messages; create policy "Public can submit contact messages" on public.contact_messages for insert to anon,authenticated with check (char_length(name) between 1 and 120 and char_length(email) between 3 and 320 and char_length(message) between 1 and 5000);